type Pt = [number, number];
type Fig = Build & { mood?: Mood };
/** A figure (with mood face) whose arms are posed: `l`/`r` are canvas points (elbow …, hand) for the arm on that side. */
const F = (b: Fig, l?: Pt[], r?: Pt[]): Svg => {
  const x = b.x ?? 60, s = 0.84 * (b.h ?? 1), y0 = 112 - 49 * s;
  const col = b.grey ? C.grey : (b.top ?? C.sky), sk = b.grey ? C.grey2 : C.skin;
  const limb = (side: 1 | -1, pts: Pt[]) => {
    const sh: Pt = [x + side * 12 * s, y0 - 37 * s];
    const d = 'M' + [sh, ...pts].map(([a, c]) => `${f1(a)} ${f1(c)}`).join(' L');
    const h = pts[pts.length - 1]!;
    return all(g(`translate(${f1(x)} ${f1(y0)}) scale(${f1(side * s)} ${f1(s)})`, path('M14.9 -45 L25 -45 L25 4 L14.2 4 L14.2 -20 L14.9 -30 Z', C.paper, null)), line(d, C.ink, 7.4 * s), line(d, col, 4.8 * s), circle(h[0], h[1], 3.1 * s, sk, C.ink, 1.1));
  };
  return all(P(b), r ? limb(1, r) : '', l ? limb(-1, l) : '');
};
