const back = (x: number, y: number, col: string, hair: string = C.hair, long = false) => all(path(`M${x - 13} ${y + 22} C${x - 13} ${y + 8} ${x + 13} ${y + 8} ${x + 13} ${y + 22} Z`, col, C.ink, 1.4), long ? path(`M${x - 9} ${y + 8} C${x - 10} ${y - 2} ${x + 10} ${y - 2} ${x + 9} ${y + 8} Z`, hair, C.ink, 1.2) : '', circle(x, y, 8, hair, C.ink, 1.4));

