/** A balance scale tilted by `tilt` (− = left side down) with items on the pans. */
const scale = (x: number, y: number, tilt: number, left: Svg, right: Svg, s = 1) => {
  const a = (tilt * Math.PI) / 180, dx = Math.cos(a) * 30, dy = Math.sin(a) * 30;
  const L: Pt = [x - dx, y - dy], R: Pt = [x + dx, y + dy];
  const pan = ([px, py]: Pt, item: Svg) => all(line(`M${px} ${py} L${px - 10} ${py + 14} M${px} ${py} L${px + 10} ${py + 14}`, C.ink, 1), path(`M${px - 13} ${py + 14} L${px + 13} ${py + 14} C${px + 10} ${py + 20} ${px - 10} ${py + 20} ${px - 13} ${py + 14} Z`, '#e0b23c', C.ink, 1.2), g(`translate(${f1(px)} ${f1(py + 8)})`, item));
  return g(`translate(${x} ${y}) scale(${s}) translate(${-x} ${-y})`, rect(x - 2, y, 4, 40, '#8a6a3a', 1, C.ink, 1.1), rect(x - 12, y + 38, 24, 5, '#8a6a3a', 2, C.ink, 1.1), line(`M${f1(L[0])} ${f1(L[1])} L${f1(R[0])} ${f1(R[1])}`, C.ink, 2.6), circle(x, y, 3, '#e0b23c', C.ink, 1), pan(L, left), pan(R, right));
};
